func exportDNA(dna schema.DNA_Schema, formats []string) {
	var compilers []compiler.Compiler
	for _, f := range formats {
		switch f {
		case "json":
			compilers = append(compilers, &compiler.JSONCompiler{})
		case "markdown":
			compilers = append(compilers, &compiler.MarkdownCompiler{})
		case "cursor":
			compilers = append(compilers, &compiler.CursorCompiler{})
		case "copilot":
			compilers = append(compilers, &compiler.CopilotCompiler{})
		case "antigravity":
			compilers = append(compilers, &compiler.AntigravityCompiler{})
		case "claude":
			compilers = append(compilers, &compiler.ClaudeCompiler{})
		case "continue":
			compilers = append(compilers, &compiler.ContinueCompiler{})
		case "windsurf":
			compilers = append(compilers, &compiler.WindsurfCompiler{})
		case "jetbrains":
			compilers = append(compilers, &compiler.JetBrainsCompiler{})
		}
	}

	// Always export JSON if not specified? Or just follow flags.
	// Default to JSON if nothing else.
	if len(compilers) == 0 {
		compilers = append(compilers, &compiler.JSONCompiler{})
	}

	for _, c := range compilers {
		files, err := c.Compile(dna)
		if err != nil {
			fmt.Printf("Error compiling: %v\n", err)
			continue
		}

		for filename, content := range files {
			// Ensure directory exists
			dir := filepath.Dir(filename)
			if dir != "." {
				err = os.MkdirAll(dir, 0755)
				if err != nil {
					fmt.Printf("Error creating directory %s: %v\n", dir, err)
					continue
				}
			}

			err = os.WriteFile(filename, []byte(content), 0644)
			if err != nil {
				fmt.Printf("Error writing %s: %v\n", filename, err)
			} else {
				fmt.Printf("✅ Exported standards to %s\n", filename)
			}
		}
	}
}

func (o *Optimizer) GenerateDNA(projectName string, samples []schema.Sample) schema.DNA_Schema {
	dna := schema.DNA_Schema{
		ProjectName: projectName,
		Version:     "0.1.0",
		GeneratedAt: time.Now(),
		Standards:   []schema.Standard{},
	}

	// Group samples by some category (mocked for now)
	for i, s := range samples {
		std := schema.Standard{
			ID:          fmt.Sprintf("STD-%d", i),
			Title:       fmt.Sprintf("Pattern Detected in %s", s.FilePath),
			Category:    "General",
			Rationale:   "Automatically extracted from codebase structure.",
			Samples:     []schema.Sample{s},
			Rules:       []string{"Follow the structural pattern demonstrated in the sample."},
		}
		dna.Standards = append(dna.Standards, std)
	}

	return dna
}

func (c *JSONCompiler) Compile(dna schema.DNA_Schema) (map[string]string, error) {
	data, err := json.MarshalIndent(dna, "", "  ")
	if err != nil {
		return nil, err
	}
	return map[string]string{
		"codedna.json": string(data),
	}, nil
}

func (m model) parseFiles(files []string) tea.Cmd {
	return func() tea.Msg {
		var allBlocks []parser.CodeBlock
		for _, f := range files {
			ext := filepath.Ext(f)
			p := parser.NewParser(ext)
			if p == nil {
				continue
			}

			blocks, err := p.ExtractBlocks(f)
			if err == nil {
				allBlocks = append(allBlocks, blocks...)
			}
		}

		// Now clustering
		cm, err := cluster.NewClusterManager("dna", dummyEmbedder)
		if err != nil {
			return logMsg{text: fmt.Sprintf("Cluster error: %v", err)}
		}

		ctx := context.Background()
		err = cm.AddBlocks(ctx, allBlocks)
		if err != nil {
			return logMsg{text: fmt.Sprintf("Add blocks error: %v", err)}
		}

		clusters, err := cm.GroupByPattern(ctx, allBlocks)
		if err != nil {
			return logMsg{text: fmt.Sprintf("Grouping error: %v", err)}
		}

		// Select golden samples
		opt := optimizer.NewOptimizer(4096)
		samples := opt.SelectGoldenSamples(clusters)
		dna := opt.GenerateDNA("Project", samples)

		return clusteringFinishedMsg{
			dna: dna,
		}
	}
}

func (cm *ClusterManager) GroupByPattern(
	ctx context.Context, blocks []parser.CodeBlock) (map[string][]parser.CodeBlock, error) {
	clusters := make(map[string][]parser.CodeBlock)
	seen := make(map[string]bool)

	for _, block := range blocks {
		if seen[block.Content] {
			continue
		}

		// Use the first few lines as a "pattern" key if we find similar ones
		// In a real implementation, we'd use k-means or similar on embeddings.
		// For now, we'll query for similar blocks and group them.
		similar, err := cm.FindSimilar(ctx, block.Content, 5)
		if err != nil {
			continue
		}

		clusterID := fmt.Sprintf("pattern-%d", len(clusters))
		for _, s := range similar {
			if !seen[s.Content] {
				clusters[clusterID] = append(clusters[clusterID], s)
				seen[s.Content] = true
			}
		}
	}

	return clusters, nil
}

func TestContinueCompiler(t *testing.T) {
	c := &ContinueCompiler{}
	dna := schema.DNA_Schema{
		ProjectName: "TestProject",
		Standards: []schema.Standard{
			{
				Title:       "Error Handling",
				Description: "Error rules",
				Samples: []schema.Sample{
					{FilePath: "internal/errs/errors.go"},
				},
				Rules: []string{"Wrap errors"},
			},
		},
	}

	files, err := c.Compile(dna)
	if err != nil {
		t.Fatalf("Compile failed: %v", err)
	}

	expectedFile := ".continue/rules/error_handling.md"
	content, ok := files[expectedFile]
	if !ok {
		t.Fatalf("Missing expected file: %s", expectedFile)
	}

	if !strings.Contains(content, "name: Error Handling") {
		t.Error("Missing name in frontmatter")
	}
	if !strings.Contains(content, "internal/errs/**/*.go") {
		t.Errorf("Expected glob internal/errs/**/*.go, got: %s", content)
	}
}

func (p *Parser) ExtractBlocks(path string) ([]CodeBlock, error) {
	content, err := os.ReadFile(filepath.Clean(path))
	if err != nil {
		return nil, err
	}

	cpp := sitter.NewParser()
	cpp.SetLanguage(p.Language)

	tree, err := cpp.ParseCtx(context.Background(), nil, content)
	if err != nil {
		return nil, err
	}

	n := tree.RootNode()

	q, err := sitter.NewQuery([]byte(p.Query), p.Language)
	if err != nil {
		return nil, err
	}

	qc := sitter.NewQueryCursor()
	qc.Exec(q, n)

	var blocks []CodeBlock
	for {
		m, ok := qc.NextMatch()
		if !ok {
			break
		}
		for _, c := range m.Captures {
			kind := q.CaptureNameForId(c.Index)
			// Map internal capture names to user-friendly kinds
			switch kind {
			case "func":
				kind = "function"
			case "method":
				kind = "method"
			case "class":
				kind = "class"
			case "interface":
				kind = "interface"
			}

			blocks = append(blocks, CodeBlock{
				Content:  c.Node.Content(content),
				Kind:     kind,
				FilePath: path,
			})
		}
	}

	return blocks, nil
}

