func (c *ContinueCompiler) Compile(dna schema.DNA_Schema) (map[string]string, error) {
	outputs := make(map[string]string)

	for _, s := range dna.Standards {
		var sb strings.Builder

		// Determine globs from samples
		globMap := make(map[string]bool)
		for _, sample := range s.Samples {
			dir := filepath.Dir(sample.FilePath)
			ext := filepath.Ext(sample.FilePath)
			if dir == "." {
				globMap["*"+ext] = true
			} else {
				globMap[dir+"/**/*"+ext] = true
			}
		}

		var globs []string
		for g := range globMap {
			globs = append(globs, g)
		}

		// YAML Frontmatter
		sb.WriteString("---\n")
		sb.WriteString(fmt.Sprintf("name: %s\n", s.Title))
		sb.WriteString(fmt.Sprintf("description: %s\n", s.Description))
		sb.WriteString("globs:\n")
		if len(globs) == 0 {
			sb.WriteString("  - \"**/*\"\n")
		} else {
			for _, g := range globs {
				sb.WriteString(fmt.Sprintf("  - \"%s\"\n", g))
			}
		}
		sb.WriteString("alwaysApply: false\n")
		sb.WriteString("---\n\n")

		sb.WriteString("# " + s.Title + "\n\n")
		sb.WriteString(s.Description + "\n\n")
		sb.WriteString("## Guidelines\n")
		for _, rule := range s.Rules {
			sb.WriteString(fmt.Sprintf("- %s\n", rule))
		}

		filename := sanitizeFilename(s.Title)
		fullPath := fmt.Sprintf(".continue/rules/%s.md", filename)
		outputs[fullPath] = sb.String()
	}

	return outputs, nil
}

func TestAntigravityCompiler(t *testing.T) {
	c := &AntigravityCompiler{}
	dna := schema.DNA_Schema{
		ProjectName: "TestProject",
		Standards: []schema.Standard{
			{
				Title:    "Logging Pattern",
				Category: "Logging",
				Rationale: "Consistent logging is good.",
				Rules:    []string{"Use JSON logging", "Include trace ID"},
				Samples: []schema.Sample{
					{
						FilePath: "main.go",
						Language: "go",
						Content:  "log.Info().Msg(\"hello\")",
					},
				},
			},
			{
				Title:    "Error Handling",
				Category: "Errors",
				Rationale: "Wrap errors.",
				Rules:    []string{"Wrap with %w"},
			},
		},
	}

	files, err := c.Compile(dna)
	if err != nil {
		t.Fatalf("Compile failed: %v", err)
	}

	if len(files) != 2 {
		t.Errorf("Expected 2 files, got %d", len(files))
	}

	expectedFiles := []string{
		".agents/rules/logging_pattern.md",
		".agents/rules/error_handling.md",
	}

	for _, ef := range expectedFiles {
		if _, ok := files[ef]; !ok {
			t.Errorf("Missing expected file: %s", ef)
		}
	}

	// Check content of one file
	content := files[".agents/rules/logging_pattern.md"]
	if len(content) == 0 {
		t.Error("Empty content for logging_pattern.md")
	}
	if len(content) > 12000 {
		t.Error("Content exceeds 12,000 characters")
	}
}

func (c *JetBrainsCompiler) Compile(dna schema.DNA_Schema) (map[string]string, error) {
	outputs := make(map[string]string)

	for _, s := range dna.Standards {
		var sb strings.Builder

		// Determine pattern from samples
		globMap := make(map[string]bool)
		for _, sample := range s.Samples {
			dir := filepath.Dir(sample.FilePath)
			ext := filepath.Ext(sample.FilePath)
			if dir == "." {
				globMap["*"+ext] = true
			} else {
				globMap[dir+"/**/*"+ext] = true
			}
		}

		var globs []string
		for g := range globMap {
			globs = append(globs, g)
		}

		// YAML Frontmatter
		sb.WriteString("---\n")
		sb.WriteString("type: file patterns\n")
		sb.WriteString("pattern: \"")
		if len(globs) == 0 {
			sb.WriteString("**/*")
		} else {
			sb.WriteString(strings.Join(globs, ", "))
		}
		sb.WriteString("\"\n")
		sb.WriteString("---\n\n")

		sb.WriteString("# " + s.Title + "\n\n")
		sb.WriteString(s.Description + "\n\n")
		sb.WriteString("## Guidelines\n")
		for _, rule := range s.Rules {
			sb.WriteString(fmt.Sprintf("- %s\n", rule))
		}

		filename := sanitizeFilename(s.Title)
		fullPath := fmt.Sprintf(".aiassistant/rules/%s.md", filename)
		outputs[fullPath] = sb.String()
	}

	return outputs, nil
}

func (c *ClaudeCompiler) Compile(dna schema.DNA_Schema) (map[string]string, error) {
	outputs := make(map[string]string)

	// 1. Generate Lean CLAUDE.md
	var mainSb strings.Builder
	mainSb.WriteString("# " + dna.ProjectName + "\n\n")
	mainSb.WriteString("## Project Summary\n")
	mainSb.WriteString("Engineering standards and patterns extracted by CodeDNA.\n\n")
	mainSb.WriteString("## Standards Overview\n")
	for _, s := range dna.Standards {
		mainSb.WriteString(fmt.Sprintf("- [%s](.claude/rules/%s.md): %s\n", s.Title, sanitizeFilename(s.Title), s.Description))
	}
	outputs["CLAUDE.md"] = mainSb.String()

	// 2. Generate Modular Rules
	for _, s := range dna.Standards {
		var sb strings.Builder

		// Determine paths from samples
		pathMap := make(map[string]bool)
		for _, sample := range s.Samples {
			dir := filepath.Dir(sample.FilePath)
			ext := filepath.Ext(sample.FilePath)
			if dir == "." {
				pathMap["*"+ext] = true
			} else {
				pathMap[dir+"/**/*"+ext] = true
			}
		}

		var paths []string
		for p := range pathMap {
			paths = append(paths, p)
		}

		// YAML Frontmatter (Claude uses 'paths')
		sb.WriteString("---\n")
		sb.WriteString("paths:\n")
		if len(paths) == 0 {
			sb.WriteString("  - \"**/*\"\n")
		} else {
			for _, p := range paths {
				sb.WriteString(fmt.Sprintf("  - \"%s\"\n", p))
			}
		}
		sb.WriteString("---\n\n")

		sb.WriteString("# " + s.Title + "\n\n")
		sb.WriteString(s.Description + "\n\n")
		sb.WriteString("## Guidelines\n")
		for _, rule := range s.Rules {
			sb.WriteString(fmt.Sprintf("- %s\n", rule))
		}

		filename := sanitizeFilename(s.Title)
		fullPath := fmt.Sprintf(".claude/rules/%s.md", filename)
		outputs[fullPath] = sb.String()
	}

	return outputs, nil
}

func (c *AntigravityCompiler) Compile(dna schema.DNA_Schema) (map[string]string, error) {
	outputs := make(map[string]string)

	for _, s := range dna.Standards {
		var sb strings.Builder
		sb.WriteString(fmt.Sprintf("# %s\n\n", s.Title))
		sb.WriteString(fmt.Sprintf("Category: %s\n", s.Category))
		sb.WriteString(fmt.Sprintf("Rationale: %s\n\n", s.Rationale))
		sb.WriteString("## Guidelines\n")
		for _, rule := range s.Rules {
			sb.WriteString(fmt.Sprintf("- %s\n", rule))
		}

		if len(s.Samples) > 0 {
			sb.WriteString("\n## Examples\n")
			for _, sample := range s.Samples {
				sb.WriteString(fmt.Sprintf("```%s\n// File: %s\n%s\n```\n\n", sample.Language, sample.FilePath, sample.Content))
			}
		}

		// Sanitize title for filename
		filename := strings.ToLower(s.Title)
		filename = strings.ReplaceAll(filename, " ", "_")
		filename = strings.ReplaceAll(filename, "/", "_")
		fullPath := fmt.Sprintf(".agents/rules/%s.md", filename)

		content := sb.String()
		// Limit to 12,000 chars as per Antigravity docs
		if len(content) > 12000 {
			content = content[:11997] + "..."
		}

		outputs[fullPath] = content
	}

	return outputs, nil
}

func (m model) View() string {
	if m.width == 0 {
		return "Initializing..."
	}

	// 1. Header
	header := titleStyle.Render("CodeDNA 🧬") + " " + subtleStyle.Render("v0.1.0") + " | " + infoStyle.Render(m.path)
	header = headerStyle.Width(m.width - 2).Render(header)

	// 2. Body (Two Columns)
	sidebarWidth := m.width / 4
	if sidebarWidth < 25 {
		sidebarWidth = 25
	}
	mainWidth := m.width - sidebarWidth - 6

	// Sidebar: Engineering DNA Summary
	var sidebarBuilder strings.Builder
	sidebarBuilder.WriteString(dnaStyle.Render("ENGINEERING DNA") + "\n\n")

	if len(m.patternsFound) > 0 {
		for _, p := range m.patternsFound {
			fmt.Fprintf(&sidebarBuilder, " %s %s\n", successStyle.Render("✔"), p)
		}
	} else if m.step == done {
		sidebarBuilder.WriteString(subtleStyle.Render(" No patterns detected.\n"))
	} else {
		fmt.Fprintf(&sidebarBuilder, " %s Analyzing code...\n", m.spinner.View())
	}

	if m.step == done {
		sidebarBuilder.WriteString(
			"\n" + lipgloss.NewStyle().Foreground(lipgloss.Color("#FFCC00")).Bold(true).Render("SUMMARY") + "\n")
		fmt.Fprintf(&sidebarBuilder, " Files: %d\n", m.totalFiles)
		fmt.Fprintf(&sidebarBuilder, " Patterns: %d\n", len(m.patternsFound))
	}

	sidebar := focusedStyle.Width(sidebarWidth).Height(m.height - 10).Render(sidebarBuilder.String())

	// Main: Extraction Logs
	var mainBuilder strings.Builder
	mainBuilder.WriteString(lipgloss.NewStyle().Bold(true).Render("EXTRACTION LOGS") + "\n\n")
	for _, log := range m.logs {
		icon := infoStyle.Render("→")
		if strings.Contains(log, "Clustered") || strings.Contains(log, "Selected") {
			icon = successStyle.Render("✔")
		}
		fmt.Fprintf(&mainBuilder, " %s %s\n", icon, log)
	}
	if m.step != done {
		fmt.Fprintf(&mainBuilder, "\n %s Current: %s", m.spinner.View(), infoStyle.Render(m.currentFile))
	} else {
		mainBuilder.WriteString("\n " + successStyle.Render("⠿") + " All rules synthesized in internal schema.")
	}
	mainArea := columnStyle.Width(mainWidth).Height(m.height - 10).Render(mainBuilder.String())

	body := lipgloss.JoinHorizontal(lipgloss.Top, sidebar, mainArea)

	// 3. Status Bar & Footer
	status := "READY"
	statusColor := lipgloss.Color("#3C3C3C")
	switch m.step {
	case scanningFiles:
		status = "SCANNING"
		statusColor = lipgloss.Color("#00BFFF")
	case parsingAST:
		status = "PARSING"
		statusColor = lipgloss.Color("#7D56F4")
	case clustering:
		status = "CLUSTERING"
		statusColor = lipgloss.Color("#FF00FF")
	case done:
		status = "COMPLETE"
		statusColor = lipgloss.Color("#00FF00")
	}

	statusView := footerStyle.Background(statusColor).Render(status)

	// Progress bar with fixed width
	m.progress.Width = m.width / 2
	progressBar := m.progress.View()

	footer := lipgloss.JoinHorizontal(lipgloss.Center,
		statusView,
		"  ",
		progressBar,
		"  ",
		subtleStyle.Render("press q to exit"),
	)

	return lipgloss.JoinVertical(lipgloss.Left,
		header,
		body,
		footer,
	)
}

func (c *MarkdownCompiler) Compile(dna schema.DNA_Schema) (map[string]string, error) {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("# %s: Engineering Standards\n\n", dna.ProjectName))
	sb.WriteString(fmt.Sprintf("*Generated by CodeDNA on %s*\n\n", dna.GeneratedAt.Format("2006-01-02")))

	for _, s := range dna.Standards {
		sb.WriteString(fmt.Sprintf("## %s\n", s.Title))
		sb.WriteString(fmt.Sprintf("> %s\n\n", s.Rationale))
		sb.WriteString("### Patterns Detected\n")
		for _, p := range s.Patterns {
			sb.WriteString(fmt.Sprintf("- `%s`\n", p))
		}
		sb.WriteString("\n### Guidelines\n")
		for _, rule := range s.Rules {
			sb.WriteString(fmt.Sprintf("- %s\n", rule))
		}
		sb.WriteString("\n---\n\n")
	}

	return map[string]string{
		"CODEDNA_STANDARDS.md": sb.String(),
	}, nil
}

